    // ---- Streaming datapath + control FSM ----
    always @(posedge clk) begin
        if (rst) begin
            state <= 0; cnt <= 0; done <= 0;
            for (i=0;i<128;i=i+1) acc0[i] <= 0.0;
            for (i=0;i<64;i=i+1) acc1[i] <= 0.0;
            for (i=0;i<10;i=i+1) acc2[i] <= 0.0;
        end else begin
            done <= 0;
            if (state == 0) begin
                if (start) begin
                    state <= 1; cnt <= 0;
                    for (i=0;i<128;i=i+1) acc0[i] <= 0.0;
                end
            end
            else if (state == 1) begin
                for (i=0;i<128;i=i+1)
                    acc0[i] <= acc0[i] + act_in * w0[i][cnt];
                if (cnt == 783) begin
                    state <= 2; cnt <= 0;
                    for (i=0;i<128;i=i+1) begin
                        buf0[i] <= acc0[i] + act_in * w0[i][cnt];
                    end
                    for (i=0;i<64;i=i+1) acc1[i] <= 0.0;
                end else begin
                    cnt <= cnt + 1;
                end
            end
            else if (state == 2) begin
                for (i=0;i<64;i=i+1)
                    acc1[i] <= acc1[i] + buf0[cnt] * w1[i][cnt];
                if (cnt == 127) begin
                    state <= 3; cnt <= 0;
                    for (i=0;i<64;i=i+1) begin
                        buf1[i] <= acc1[i] + buf0[cnt] * w1[i][cnt];
                    end
                    for (i=0;i<10;i=i+1) acc2[i] <= 0.0;
                end else begin
                    cnt <= cnt + 1;
                end
            end
            else if (state == 3) begin
                for (i=0;i<10;i=i+1)
                    acc2[i] <= acc2[i] + buf1[cnt] * w2[i][cnt];
                if (cnt == 63) begin
                    state <= 0; cnt <= 0; done <= 1;
                    out0 <= acc2[0] + buf1[cnt] * w2[0][cnt];
                    out1 <= acc2[1] + buf1[cnt] * w2[1][cnt];
                    out2 <= acc2[2] + buf1[cnt] * w2[2][cnt];
                    out3 <= acc2[3] + buf1[cnt] * w2[3][cnt];
                    out4 <= acc2[4] + buf1[cnt] * w2[4][cnt];
                    out5 <= acc2[5] + buf1[cnt] * w2[5][cnt];
                    out6 <= acc2[6] + buf1[cnt] * w2[6][cnt];
                    out7 <= acc2[7] + buf1[cnt] * w2[7][cnt];
                    out8 <= acc2[8] + buf1[cnt] * w2[8][cnt];
                    out9 <= acc2[9] + buf1[cnt] * w2[9][cnt];
                end else begin
                    cnt <= cnt + 1;
                end
            end
        end
    end
